using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeOpenRoadsideUpgrade{const string D="Assets/Scenes/Oasis/CoffeeShopUpgrade/";static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static CoffeeOpenRoadsideUpgrade(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeOpenRoadsideUpgrade.request"))return;File.Delete("CoffeeOpenRoadsideUpgrade.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeOpenRoadsideUpgrade.txt",e.ToString());Debug.LogException(e);}}struct V{public Vector3 p;public Vector2[] uv;}static Mesh Lower(MeshFilter f,float cutoff,string path){var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var pp=new List<Vector3>();var uu=Enumerable.Range(0,8).Select(c=>new List<Vector2>()).ToArray();var ii=new List<int>();Func<int,V> vertex=i=>new V{p=p[i],uv=Enumerable.Range(0,8).Select(c=>uv[c]!=null?uv[c][i]:Vector2.zero).ToArray()};Func<V,V,float,V> mix=(a,b,t)=>new V{p=Vector3.Lerp(a.p,b.p,t),uv=Enumerable.Range(0,8).Select(c=>Vector2.Lerp(a.uv[c],b.uv[c],t)).ToArray()};for(int k=0;k<ids.Length;k+=3){var poly=new[]{vertex(ids[k]),vertex(ids[k+1]),vertex(ids[k+2])};var clipped=new List<V>();for(int j=0;j<3;j++){var a=poly[j];var b=poly[(j+1)%3];float ay=f.transform.TransformPoint(a.p).y,by=f.transform.TransformPoint(b.p).y;bool ain=ay<=cutoff,bin=by<=cutoff;if(ain)clipped.Add(a);if(ain!=bin)clipped.Add(mix(a,b,(cutoff-ay)/(by-ay)));}for(int j=1;j<clipped.Count-1;j++){int n=pp.Count;foreach(var v in new[]{clipped[0],clipped[j],clipped[j+1]}){pp.Add(v.p);for(int c=0;c<8;c++)uu[c].Add(v.uv[c]);}ii.AddRange(new[]{n,n+1,n+2});}}var lower=new Mesh{name=f.name+" native pole platform retained"};lower.SetVertices(pp);for(int c=0;c<8;c++)if(uv[c]!=null)lower.SetUVs(c,uu[c]);lower.SetTriangles(ii,0);lower.RecalculateNormals();lower.RecalculateTangents();lower.RecalculateBounds();AssetDatabase.CreateAsset(lower,path);return lower;}
static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(scene.GetRootGameObjects().Any(g=>g.name=="Coffee Shop Open Roadside Logos"))throw new Exception("Coffee roadside signs already installed");var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray();var shops=all.Where(f=>new[]{"Circus_Circus_0 (1)","Circus_Circus_0 (2)"}.Contains(f.name)).OrderByDescending(f=>f.transform.position.x).ToArray();if(shops.Length!=2||shops[0].sharedMesh!=shops[1].sharedMesh)throw new Exception("Expected two shared coffee shop native meshes");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCoffeeOpenRoadside");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCoffeeOpenRoadside/Scene.unity",true);var mesh=shops[0].sharedMesh;File.Copy(AssetDatabase.GetAssetPath(mesh),"FinalEnvironmentRoadBackup/BeforeCoffeeOpenRoadside/CoffeeMesh.asset",true);var points=mesh.vertices;var triangles=mesh.triangles;var keep=new List<int>();var removed=new int[2];var unchanged=new List<int>();for(int k=0;k<triangles.Length;k+=3){var vs=new[]{triangles[k],triangles[k+1],triangles[k+2]}.Select(i=>shops[0].transform.TransformPoint(points[i])).ToArray();bool inside=vs.All(v=>v.x>218.27f&&v.x<226.71f&&v.y>31.435f&&v.y<33.505f);int sign=vs.All(v=>v.z>281.45f&&v.z<281.65f)?0:vs.All(v=>v.z>225.95f&&v.z<226.15f)?1:-1;if(inside&&sign>=0)removed[sign]++;else{keep.AddRange(new[]{triangles[k],triangles[k+1],triangles[k+2]});unchanged.Add(k/3);}}if(removed.Any(n=>n<100))throw new Exception("Old board removal did not locate both complete signs: "+string.Join(",",removed));mesh.SetTriangles(keep,0);mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);if(!mesh.vertices.SequenceEqual(points))throw new Exception("Unrelated cafe geometry changed");
var near=StackHouse3DSigns.BuildCoffeeOpenRoadside(true);var far=StackHouse3DSigns.BuildCoffeeOpenRoadside(false);AssetDatabase.CreateAsset(near,D+"Coffee open roadside near.asset");AssetDatabase.CreateAsset(far,D+"Coffee open roadside far.asset");var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");var master=new GameObject("Coffee Shop Open Roadside Logos");foreach(string name in new[]{"billboard (20)","billboard (46)"}){var f=all.Single(g=>g.name==name);var originalMatrix=f.transform.localToWorldMatrix;var center=f.GetComponent<Renderer>().bounds.center;float cutoff=f.transform.position.y+7.69f;var lower=Lower(f,cutoff,D+name+" original pole platform.asset");f.sharedMesh=lower;PrefabUtility.RecordPrefabInstancePropertyModifications(f);var collider=f.GetComponent<MeshCollider>();if(collider){collider.sharedMesh=lower;PrefabUtility.RecordPrefabInstancePropertyModifications(collider);}var root=new GameObject(name+" freestanding coffee cup logo");root.transform.SetParent(master.transform,false);root.transform.position=new Vector3(center.x,cutoff+.9f,center.z);var normal=name=="billboard (20)"?Vector3.right:Vector3.forward;root.transform.rotation=Quaternion.LookRotation(normal);var rr=new Renderer[2];for(int l=0;l<2;l++){var go=new GameObject(l==0?"Raised COFFEE SHOP cup and neon near":"Coffee silhouette distant");go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=l==0?near:far;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;rr[l]=r;}var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.065f,new[]{rr[0]}),new LOD(.003f,new[]{rr[1]})});lod.RecalculateBounds();if(f.transform.localToWorldMatrix!=originalMatrix)throw new Exception("Original billboard pole moved");}
PrefabUtility.SaveAsPrefabAssetAndConnect(master,D+"Coffee Shop Open Roadside Logos.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/CoffeeOpenRoadsideUpgrade.txt","SUCCESS billboard (20) and (46) rectangular heads removed, native pole/platform transforms retained. Shared two-sided low-poly raised COFFEE SHOP lettering, open cup emblem and warm neon. Existing cafe atlas and material only, no new texture/material/light. Near triangles="+near.triangles.Length/3+" far="+far.triangles.Length/3+". Old green board + red lettering removed at front/back of shared cafe mesh="+string.Join(",",removed)+" triangles; 2 cafe instances = 4 old signs removed. Other cafe triangle positions, UVs and shader flags untouched. Native remaining triangles="+keep.Count/3+". Shader errors="+ShaderUtil.ShaderHasError(mat.shader));}}
